'use strict';

// FUNCTIONS //

/**
* Returns a prototype-safe index for flow nodes.
*
* @private
* @param {Array} children - semantic children
* @param {Object} out - output index
* @returns {Object} index
*/
function recurse( children, out ) {
	var ch;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		ch = children[ i ];
		out[ ch.id ] = ch;
		if ( ch.children ) {
			recurse( ch.children, out );
		}
	}
	return out;
}


// MAIN //

/**
* Returns a prototype-safe index for flow nodes.
*
* @private
* @param {Array} children - semantic children
* @returns {Object} index
*/
function flowIndex( children ) {
	var out = Object.create( null );
	return recurse( children, out );
}


// EXPORTS //

module.exports = flowIndex;
